import Dependant from "../models/dependant";
import User from "../models/user";
import { getAge } from "./authUtils";

const dependantsTransform = (dependants) => {
  let transformedData = [];

  dependants.map((i) => {
    transformedData.push(
      new Dependant(
        i.id,
        i.first_name,
        i.last_name,
        `${i.last_name} ${i.first_name}`,
        i.gender ? i.gender : "N/A",
        i.date_of_birth,
        getAge(i.date_of_birth),
        i.user,
        `${i.owner_details.first_name} ${i.owner_details.last_name}`,
        i.owner_details.phone,
        i.images && i.images.length > 0
          ? i.images[0].image
          : "https://cdn.pixabay.com/photo/2018/03/22/02/37/background-3249063_960_720.png"
      )
    );
  });
  return transformedData;
};

const usersTransform = (users) => {
  let transformedData = [];

  users.map((i) => {
    transformedData.push(
      new User(
        i.id,
        i.entity,
        i.entity_title,
        `${i.first_name} ${i.last_name}`,
        i.first_name,
        i.last_name,
        null,
        i.national_id,
        i.email,
        i.phone,
        i.date_of_birth,
        i.country_details ? i.country_details.id : "",
        i.country_details ? i.country_details.title : "",
        i.country_details ? i.county_details.id : "",
        i.county_details ? i.county_details.title : "",
        i.images ? i.images[0].image : null,
        i.is_verified,

      )
    );
  });
  return transformedData;
};
export default { dependantsTransform, usersTransform };
